run:pattern = re.compile(r'''
 let buildFailed = false;
 let buildOutput = "";
 try \{
 buildOutput = execFileSync\("npx", \["next", "build"\], \{
 cwd: EXAMPLE_ROOT,
 encoding: "utf8",
 timeout: 90_000,
 \}\);
 \} catch \(err\) \{
 buildFailed = true;
 buildOutput = String\(\(err as \{ stdout\?: string \}\)\.stdout \?\? \(err as Error\)\.message\);
 \}
 // Real, reproduced fact \(not assumed from a stale prior run\): the
 // production build currently fails at exactly the disclosed chunk\.
 expect\(buildFailed\)\.toBe\(true\);
 expect\(buildOutput\)\.toContain\("node:module"\);''')

run:replacement = '''
 const buildOutput = execFileSync("npm", ["run", "build"], {
 cwd: EXAMPLE_ROOT,
 encoding: "utf8",
 timeout: 180_000,
 });
 expect(typeof buildOutput).toBe("string");'''

run:s = re.sub(r'''const FALLBACK_CHROMIUM_PATHS = \[.*?\];

export function resolveExecutablePath\(\): string \| undefined \{
 return FALLBACK_CHROMIUM_PATHS\.find\(\(p\) => existsSync\(p\)\);
\}''', '''export function resolveExecutablePath(): string | undefined {
 const candidates = [process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE, chromium.executablePath()];
 return candidates.find((candidate): candidate is string => typeof candidate === "string" && existsSync(candidate));
}''', s, flags=re.S)

